package com.ascend.invest;

import android.graphics.Color;
import android.graphics.drawable.Drawable;
import android.os.Bundle;
import android.text.TextUtils;
import android.view.View;
import android.widget.EditText;
import android.widget.ImageView;
import android.widget.LinearLayout;
import android.widget.Toast;

import androidx.activity.EdgeToEdge;
import androidx.annotation.NonNull;
import androidx.appcompat.app.AppCompatActivity;
import androidx.core.content.ContextCompat;
import androidx.core.graphics.Insets;
import androidx.core.view.ViewCompat;
import androidx.core.view.WindowInsetsCompat;
import androidx.drawerlayout.widget.DrawerLayout;
import androidx.core.view.GravityCompat;

import com.github.mikephil.charting.charts.BarChart;
import com.github.mikephil.charting.charts.LineChart;
import com.github.mikephil.charting.components.XAxis;
import com.github.mikephil.charting.data.BarData;
import com.github.mikephil.charting.data.BarDataSet;
import com.github.mikephil.charting.data.BarEntry;
import com.github.mikephil.charting.data.Entry;
import com.github.mikephil.charting.data.LineData;
import com.github.mikephil.charting.data.LineDataSet;
import com.github.mikephil.charting.formatter.IndexAxisValueFormatter;
import com.google.firebase.auth.FirebaseAuth;
import com.google.firebase.database.DataSnapshot;
import com.google.firebase.database.DatabaseError;
import com.google.firebase.database.DatabaseReference;
import com.google.firebase.database.FirebaseDatabase;
import com.google.firebase.database.ValueEventListener;

import java.text.SimpleDateFormat;
import java.util.ArrayList;
import java.util.Date;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

public class MainActivity extends AppCompatActivity {

    private FirebaseAuth mAuth;
    private DatabaseReference mDatabase;
    private String userId;
    private String username = "user";

    private TransactionHandler transactionHandler;

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        EdgeToEdge.enable(this);
        setContentView(R.layout.activity_home);

        mAuth = FirebaseAuth.getInstance();
        mDatabase = FirebaseDatabase.getInstance().getReference();

        if (mAuth.getCurrentUser() != null) {
            userId = mAuth.getCurrentUser().getUid();
            fetchUsernameAndInitialize();
        } else {
            initializeUI();
        }
    }

    private void fetchUsernameAndInitialize() {
        mDatabase.child("users").child(userId).child("username").addListenerForSingleValueEvent(new ValueEventListener() {
            @Override
            public void onDataChange(@NonNull DataSnapshot snapshot) {
                if (snapshot.exists()) {
                    username = snapshot.getValue(String.class);
                }
                initializeUI();
            }

            @Override
            public void onCancelled(@NonNull DatabaseError error) {
                initializeUI();
            }
        });
    }

    private void initializeUI() {
        DrawerLayout drawerLayout = findViewById(R.id.drawer_layout);
        ImageView menuButton = findViewById(R.id.menu_button);
        menuButton.setOnClickListener(v -> drawerLayout.openDrawer(GravityCompat.START));

        ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.main), (v, insets) -> {
            Insets systemBars = insets.getInsets(WindowInsetsCompat.Type.systemBars());
            v.setPadding(systemBars.left, systemBars.top, systemBars.right, systemBars.bottom);
            return insets;
        });

        initializeDrawerButtons(drawerLayout);

        // Call the Transaction class handler with user_id and the main view
        transactionHandler = new TransactionHandler(findViewById(android.R.id.content));
        transactionHandler.fetchTransactions("sample_user_123");

        setupRequestListeners();

        chart();
        barchart();
        total_deposit_chart();
    }

    private void setupRequestListeners() {
        // Deposit Submit
        findViewById(R.id.deposit_button).setOnClickListener(v -> {
            EditText etAmount = findViewById(R.id.deposit_amount);
            EditText etAddress = findViewById(R.id.user_wallet_address);
            String amount = etAmount.getText().toString();
            String address = etAddress.getText().toString();

            if (TextUtils.isEmpty(amount) || TextUtils.isEmpty(address)) {
                Toast.makeText(this, "Please fill all fields", Toast.LENGTH_SHORT).show();
                return;
            }

            submitRequest("deposits_req", amount, address, "Deposit Request");
            etAmount.setText("");
            etAddress.setText("");
        });

        // Withdraw Submit
        findViewById(R.id.withdraw_button).setOnClickListener(v -> {
            EditText etAmount = findViewById(R.id.withdraw_amount);
            String amount = etAmount.getText().toString();

            if (TextUtils.isEmpty(amount)) {
                Toast.makeText(this, "Please enter amount", Toast.LENGTH_SHORT).show();
                return;
            }

            submitRequest("withdraw_req", amount, "", "Withdrawal Request");
            etAmount.setText("");
        });
    }

    private void submitRequest(String adminNode, String amount, String address, String title) {
        if (userId == null) return;

        String type = adminNode.contains("withdraw") ? "withdraw" : "deposit";
        String adminPath = "transactions/" + adminNode;
        String userPath = "users/" + userId + "/transactions/" + type;
        String userKey = username.toLowerCase().replace(" ", "") + "_" + userId;

        String requestId = mDatabase.child(userPath).push().getKey();
        if (requestId == null) return;

        long timestamp = System.currentTimeMillis();
        String date = new SimpleDateFormat("MMM d, yyyy • h:mm a", Locale.getDefault()).format(new Date(timestamp));

        Map<String, Object> transactionData = new HashMap<>();
        transactionData.put("id", requestId);
        transactionData.put("title", title);
        transactionData.put("subtitle", date + (TextUtils.isEmpty(address) ? "" : " • " + address));
        transactionData.put("amount", (type.equals("withdraw") ? "-$" : "+$") + amount);
        transactionData.put("status", "Pending");
        transactionData.put("type", type);
        transactionData.put("timestamp", timestamp);

        Map<String, Object> childUpdates = new HashMap<>();
        childUpdates.put("/" + adminPath + "/" + userKey + "/" + requestId, transactionData);
        childUpdates.put("/" + userPath + "/" + requestId, transactionData);

        mDatabase.updateChildren(childUpdates)
                .addOnSuccessListener(aVoid -> Toast.makeText(MainActivity.this, "Request Submitted Successfully", Toast.LENGTH_SHORT).show())
                .addOnFailureListener(e -> Toast.makeText(MainActivity.this, "Error: " + e.getMessage(), Toast.LENGTH_SHORT).show());
    }

    private void initializeDrawerButtons(DrawerLayout drawerLayout) {
        findViewById(R.id.dashboard_btn).setOnClickListener(v -> {
            showSection(R.id.section_dashboard);
            drawerLayout.closeDrawer(GravityCompat.START);
        });

        findViewById(R.id.deposit_btn).setOnClickListener(v -> {
            showSection(R.id.section_deposits);
            drawerLayout.closeDrawer(GravityCompat.START);
        });

        findViewById(R.id.withdraw_btn).setOnClickListener(v -> {
            showSection(R.id.section_withdraw);
            drawerLayout.closeDrawer(GravityCompat.START);
        });

        findViewById(R.id.refer_btn).setOnClickListener(v -> {
            showSection(R.id.section_refer);
            drawerLayout.closeDrawer(GravityCompat.START);
        });

        findViewById(R.id.team_btn).setOnClickListener(v -> {
            showSection(R.id.section_team);
            drawerLayout.closeDrawer(GravityCompat.START);
        });

        findViewById(R.id.plan_btn).setOnClickListener(v -> {
            showSection(R.id.section_plan);
            drawerLayout.closeDrawer(GravityCompat.START);
        });

        findViewById(R.id.logout_btn).setOnClickListener(v -> {
            mAuth.signOut();
            drawerLayout.closeDrawer(GravityCompat.START);
            finish();
        });
    }

    private void showSection(int sectionId) {
        hideAllSections();
        View section = findViewById(sectionId);
        if (section != null) {
            section.setVisibility(View.VISIBLE);
        }
    }

    private void hideAllSections() {
        int[] sections = {R.id.section_dashboard, R.id.section_deposits, R.id.section_withdraw, 
                         R.id.section_refer, R.id.section_team, R.id.section_plan};
        for (int id : sections) {
            View v = findViewById(id);
            if (v != null) v.setVisibility(View.GONE);
        }
    }

    // Chart code...
    public void chart(){
        LineChart chart = findViewById(R.id.salesChart);
        ArrayList<Entry> entries = new ArrayList<>();
        entries.add(new Entry(0, 6)); entries.add(new Entry(1, 6)); entries.add(new Entry(2, 5));
        entries.add(new Entry(3, 5)); entries.add(new Entry(4, 4)); entries.add(new Entry(5, 5));
        entries.add(new Entry(6, 5)); entries.add(new Entry(7, 6)); entries.add(new Entry(8, 6));
        LineDataSet dataSet = new LineDataSet(entries, "");
        dataSet.setColor(Color.parseColor("#28C76F"));
        dataSet.setDrawFilled(true);
        dataSet.setMode(LineDataSet.Mode.CUBIC_BEZIER);
        dataSet.setCubicIntensity(0.2f);
        dataSet.setFillColor(Color.parseColor("#A7F3D0"));
        dataSet.setDrawCircles(false);
        dataSet.setLineWidth(2f);
        dataSet.setDrawValues(false);
        Drawable drawable = ContextCompat.getDrawable(this , R.drawable.total_profit_chart_gradient);
        dataSet.setFillDrawable(drawable);
        chart.setViewPortOffsets(0f,0f,0f,0f);
        chart.setExtraOffsets(0f,0f,0f,0f);
        chart.setMinOffset(0f);
        LineData lineData = new LineData(dataSet);
        chart.setData(lineData);
        chart.getXAxis().setEnabled(false);
        chart.getAxisLeft().setEnabled(false);
        chart.getAxisRight().setEnabled(false);
        chart.getLegend().setEnabled(false);
        chart.getDescription().setEnabled(false);
        chart.setTouchEnabled(false);
        chart.invalidate();
    }

    public void barchart(){
        BarChart barChart = findViewById(R.id.barChart);
        ArrayList<BarEntry> entries = new ArrayList<>();
        entries.add(new BarEntry(0, 40f)); entries.add(new BarEntry(1, 65f)); entries.add(new BarEntry(2, 50f));
        entries.add(new BarEntry(3, 45f)); entries.add(new BarEntry(4, 95f)); entries.add(new BarEntry(5, 55f));
        entries.add(new BarEntry(6, 65f));
        BarDataSet dataSet = new BarDataSet(entries, "Weekly");
        int lightPurple = Color.parseColor("#E6E6FA");
        dataSet.setColors(new int[]{lightPurple, lightPurple, lightPurple, lightPurple, lightPurple, lightPurple, lightPurple});
        dataSet.setDrawValues(false);
        BarData data = new BarData(dataSet);
        data.setBarWidth(0.4f);
        barChart.setData(data);
        barChart.setViewPortOffsets(0f,0f,0f,0f);
        barChart.setTouchEnabled(false);
        barChart.getDescription().setEnabled(false);
        barChart.getLegend().setEnabled(false);
        barChart.getAxisRight().setEnabled(false);
        barChart.getAxisLeft().setDrawGridLines(false);
        barChart.getAxisLeft().setDrawAxisLine(false);
        barChart.getAxisLeft().setDrawLabels(false);
        XAxis xAxis = barChart.getXAxis();
        xAxis.setPosition(XAxis.XAxisPosition.BOTTOM);
        xAxis.setDrawGridLines(false);
        xAxis.setDrawAxisLine(false);
        xAxis.setTextColor(Color.GRAY);
        xAxis.setValueFormatter(new IndexAxisValueFormatter(new String[]{"Mo", "Tu", "We", "Th", "Fr", "Sa", "Su"}));
        barChart.invalidate();
    }

    public void total_deposit_chart(){
        LineChart chart = findViewById(R.id.total_deposit_line_chart);
        ArrayList<Entry> entries = new ArrayList<>();
        entries.add(new Entry(0,10)); entries.add(new Entry(1,10)); entries.add(new Entry(2,35));
        entries.add(new Entry(3,35)); entries.add(new Entry(4,25)); entries.add(new Entry(5,25));
        entries.add(new Entry(6,10)); entries.add(new Entry(7,10)); entries.add(new Entry(8,25));
        entries.add(new Entry(9,25)); entries.add(new Entry(10,40)); entries.add(new Entry(11,40));
        entries.add(new Entry(12,20)); entries.add(new Entry(13,20)); entries.add(new Entry(14,50));
        entries.add(new Entry(15,50));
        LineDataSet dataSet = new LineDataSet(entries,"");
        dataSet.setColor(Color.parseColor("#FF8C42"));
        dataSet.setLineWidth(2f);
        dataSet.setDrawCircles(false);
        dataSet.setDrawValues(false);
        dataSet.setDrawFilled(true);
        Drawable drawable = ContextCompat.getDrawable(this,R.drawable.total_deposit_chart_gradient);
        dataSet.setFillDrawable(drawable);
        chart.setData(new LineData(dataSet));
        chart.getXAxis().setEnabled(false);
        chart.getAxisLeft().setEnabled(false);
        chart.getAxisRight().setEnabled(false);
        chart.getLegend().setEnabled(false);
        chart.getDescription().setEnabled(false);
        chart.setViewPortOffsets(0f,0f,0f,0f);
        chart.setTouchEnabled(false);
        chart.invalidate();
    }

